// In-browser inference for the champion LightGBM (no server needed, works on GitHub Pages).
// Model trees: window.LGBM_MODEL, mapping constants: window.PREDICTOR_META
// (both generated by notebooks/07_website_export.ipynb). Parity with Python is checked by website/tests/check_model_parity.mjs.

// Example inputs for the preset buttons (form units)
const archetypes = {
  loyal: {
    last_plan_days: 30, last_auto_renew: 1, last_is_cancel: 0, last_amount_paid: 149, days_until_expiration: 24,
    last_payment_method: 41, hours: 32.0, active_days: 22, inactivity: 1, velocity: 0.25, skip_ratio: 0.15,
    age: 26, gender: 1, tenure: 850, city: 1, registered_via: 7
  },
  disengaging: {
    last_plan_days: 30, last_auto_renew: 0, last_is_cancel: 0, last_amount_paid: 149, days_until_expiration: -3,
    last_payment_method: 38, hours: 3.5, active_days: 4, inactivity: 15, velocity: 0.04, skip_ratio: 0.55,
    age: 24, gender: 2, tenure: 350, city: 13, registered_via: 9
  },
  discount_hopper: {
    last_plan_days: 30, last_auto_renew: 1, last_is_cancel: 1, last_amount_paid: 149, days_until_expiration: 2,
    last_payment_method: 36, hours: 1.0, active_days: 1, inactivity: 22, velocity: 0.02, skip_ratio: 0.70,
    age: 22, gender: 0, tenure: 180, city: 4, registered_via: 3
  }
};

// ---------- LightGBM tree walk (mirrors LightGBM's NumericalDecision / CategoricalDecision) ----------
function lgbmNextNode(tree, node, value) {
  let v = value;
  if (tree.cat[node]) {
    if (Number.isNaN(v)) return tree.r[node];
    const iv = Math.trunc(v);
    if (iv < 0) return tree.r[node];
    return tree.t[node].includes(iv) ? tree.l[node] : tree.r[node];
  }
  const missingType = tree.mt[node]; // 0 None, 1 Zero, 2 NaN
  if (Number.isNaN(v) && missingType !== 2) v = 0;
  if ((missingType === 1 && Math.abs(v) <= 1e-35) || (missingType === 2 && Number.isNaN(v))) {
    return tree.dl[node] ? tree.l[node] : tree.r[node];
  }
  return v <= tree.t[node] ? tree.l[node] : tree.r[node];
}

// Returns raw score and per-feature contributions (path attribution: change in node value at each split)
function lgbmPredict(x) {
  const model = window.LGBM_MODEL;
  const contrib = new Array(model.features.length).fill(0);
  let raw = 0, bias = 0;
  for (const tree of model.trees) {
    if (tree.f.length === 0) { raw += tree.leaf[0]; bias += tree.leaf[0]; continue; }
    let node = 0;
    bias += tree.v[0];
    while (node >= 0) {
      const child = lgbmNextNode(tree, node, x[tree.f[node]]);
      const childValue = child < 0 ? tree.leaf[-child - 1] : tree.v[child];
      contrib[tree.f[node]] += childValue - tree.v[node];
      if (child < 0) raw += childValue;
      node = child;
    }
  }
  return { raw, bias, contrib, prob: 1 / (1 + Math.exp(-raw)) };
}

// Python's round() (half to even), so the browser maps inputs exactly like the notebook
function pyRound(x) {
  const r = Math.round(x);
  return Math.abs(x % 1) === 0.5 && r % 2 !== 0 ? r - 1 : r;
}

// ---------- form payload -> 33 model features (same as form_to_features in notebook 04) ----------
function formToFeatures(p) {
  const meta = window.PREDICTOR_META;
  // A cancellation always comes with auto-renew on in the data; unseen combinations fall back to the cancel group
  const g = meta.group_fill[`${p.last_is_auto_renew}_${p.last_is_cancel}`] || meta.group_fill[`1_${p.last_is_cancel}`];
  const L = meta.listen_med;
  const hours = Math.max(0, p.total_secs_hours);
  const active = Math.trunc(Math.min(Math.max(p.active_days_count, 0), 31));
  const r = {
    city: p.city, registered_via: p.registered_via, gender: p.gender_encoded,
    age: p.bd_cleaned >= 10 && p.bd_cleaned <= 90 ? p.bd_cleaned : NaN, tenure_days: p.tenure_days, has_member: 1,
    has_tx: 1, tx_count: g.tx_count, total_paid: g.tx_count * p.last_amount_paid, avg_plan_days: p.last_plan_days,
    auto_renew_ratio: g.auto_renew_ratio, cancel_count: Math.max(g.cancel_count, p.last_is_cancel),
    discount_count: g.discount_count, n_payment_methods: g.n_payment_methods,
    last_payment_method: p.last_payment_method, last_plan_days: p.last_plan_days, last_amount_paid: p.last_amount_paid,
    last_auto_renew: p.last_is_auto_renew, last_is_cancel: p.last_is_cancel,
    // last transaction date = expiry date - plan length
    days_since_last_tx: Math.max(0, p.last_plan_days - p.days_until_expiration), days_until_expiration: p.days_until_expiration,
  };
  if (hours > 0 && active > 0) {
    const spd = hours * 3600 / active;
    const dsla = Math.trunc(Math.min(Math.max(p.days_since_last_active, 0), 30));
    const share = Math.min(Math.max(p.recent_activity_ratio, 0), 1);
    Object.assign(r, {
      has_logs: 1, active_days: active, total_hours: hours, secs_per_day: spd, songs_per_day: spd / L.secs_per_song,
      unique_song_ratio: L.unique_song_ratio, skip_ratio: p.skip_ratio, complete_ratio: Math.min(L.complete_ratio, 1 - p.skip_ratio),
      last7_share: share, active_days_7d: dsla >= 7 ? 0 : Math.max(1, Math.min(7, active, pyRound(active * share))),
      days_since_last_active: dsla, daily_secs_cv: L.daily_secs_cv,
    });
  } else {
    ['active_days', 'total_hours', 'secs_per_day', 'songs_per_day', 'unique_song_ratio', 'skip_ratio', 'complete_ratio',
      'last7_share', 'active_days_7d', 'daily_secs_cv', 'has_logs'].forEach(k => { r[k] = 0; });
    r.days_since_last_active = 31;
  }
  return window.LGBM_MODEL.features.map(f => Number(r[f]));
}

// ---------- plain-language labels for the drivers ----------
const FEATURE_TEXT = {
  last_auto_renew: v => v ? 'Auto-renew is on' : 'Auto-renew is off (manual renewal)',
  last_is_cancel: v => v ? 'A cancellation was logged' : 'No cancellation logged',
  days_until_expiration: v => v < 0 ? `Plan already expired ${-v} days before the cutoff` : `Plan expires ${v} days after the cutoff`,
  last_plan_days: v => `Plan length ${v} days`,
  avg_plan_days: v => `Average plan length ${v} days`,
  last_amount_paid: v => `Last payment ${v} NTD`,
  total_paid: v => `Estimated lifetime payments ${Math.round(v)} NTD`,
  last_payment_method: v => `Payment method ${v}`,
  auto_renew_ratio: v => `Typical auto-renew history (${Math.round(v * 100)}% of past transactions)`,
  tx_count: v => `Typical transaction history (${Math.round(v)} payments)`,
  cancel_count: v => `${v} cancellation(s) on record`,
  days_since_last_tx: v => `Last payment ${Math.round(v)} days before cutoff`,
  total_hours: v => `${v.toFixed(1)} listening hours in March`,
  active_days: v => `Active on ${v} of 31 days`,
  secs_per_day: v => `${(v / 3600).toFixed(1)} h per active day`,
  songs_per_day: v => `About ${Math.round(v)} songs per active day`,
  days_since_last_active: v => v >= 31 ? 'No listening at all in March' : `Last listened ${v} days before cutoff`,
  last7_share: v => `${Math.round(v * 100)}% of March listening was in the last 7 days`,
  active_days_7d: v => `Active on ${v} of the last 7 days`,
  skip_ratio: v => `${Math.round(v * 100)}% of songs skipped early`,
  complete_ratio: v => `${Math.round(v * 100)}% of songs played to the end`,
  has_logs: v => v ? 'Has March listening activity' : 'No March listening activity',
  tenure_days: v => `Account age ${Math.round(v / 365 * 10) / 10} years`,
  age: v => Number.isNaN(v) ? 'Age not given' : `Age ${v}`,
  city: v => `City ${v}`,
  registered_via: v => `Registration channel ${v}`,
  gender: v => ['Gender not given', 'Female', 'Male'][v] || 'Gender',
};

function describe(name, value) {
  const f = FEATURE_TEXT[name];
  return f ? f(value) : `${name} = ${value}`;
}

function computeClientSidePrediction(payload) {
  const meta = window.PREDICTOR_META;
  const x = formToFeatures(payload);
  const out = lgbmPredict(x);
  const prob = out.prob;
  const tau = meta.threshold;
  const feats = window.LGBM_MODEL.features;

  // Group the listening-derived features so the drivers read naturally
  const ranked = feats.map((f, i) => ({ f, c: out.contrib[i], v: x[i] }))
    .filter(d => Math.abs(d.c) > 0.02)
    .sort((a, b) => Math.abs(b.c) - Math.abs(a.c));
  const risks = ranked.filter(d => d.c > 0).slice(0, 4).map(d => `${describe(d.f, d.v)} (+${d.c.toFixed(2)} log-odds)`);
  const protect = ranked.filter(d => d.c < 0).slice(0, 4).map(d => `${describe(d.f, d.v)} (${d.c.toFixed(2)} log-odds)`);

  const band = meta.score_bins.find(b => prob >= b.lo && prob < b.hi) || meta.score_bins[meta.score_bins.length - 1];

  let tier = 'Low risk', color = '#15803D',
    rec = 'No action needed: this profile looks like subscribers who renew.';
  if (prob >= 0.7) {
    tier = 'Very high risk'; color = '#B91C1C';
    rec = 'Most subscribers with this score churned. A retention offer or a prompt to re-enable auto-renew is worth sending.';
  } else if (prob >= tau) {
    tier = 'High risk'; color = '#B45309';
    rec = 'Above the decision threshold: this subscriber would be flagged for a retention action.';
  } else if (prob >= tau / 3) {
    tier = 'Moderate risk'; color = '#1D4ED8';
    rec = 'Below the threshold, but higher than average. Worth monitoring.';
  }

  return {
    churn_probability: prob,
    churn_prediction: prob >= tau ? 1 : 0,
    optimal_threshold: tau,
    risk_tier: tier,
    risk_color: color,
    score_band: band,
    primary_risk_factors: risks,
    protective_factors: protect,
    retention_recommendation: rec,
    inference_source: 'LightGBM champion, running in your browser',
  };
}

// Expose for tests and the UI
window.lgbmPredict = lgbmPredict;
window.formToFeatures = formToFeatures;
window.computeClientSidePrediction = computeClientSidePrediction;
